nsresult MboxMsgInputStream::Continue(bool& more) {
  MutexAutoLock lock(mLock);
  more = false;

  // Can't continue if the stream was closed.
  if (mStatus == NS_BASE_STREAM_CLOSED) {
    return NS_BASE_STREAM_CLOSED;
  }

  MOZ_ASSERT(NS_SUCCEEDED(mStatus));
  MOZ_ASSERT(mParser->IsFinished());
  // Record start of the next message (or EOF).
  mMsgOffset = mTotalUsed;

  // Tell the parser to start on the next message
  mParser->Kick();
  mStatus = PumpData();
  if (NS_FAILED(mStatus)) {
    return mStatus;
  }
  if (mParser->AtEOF()) {
    // No more messages.
    return NS_OK;
  }

  more = true;
  return NS_OK;

// Start reading first message async.
// Note: The pump doesn't close the stream when complete.
// This is important because we want to use Continue() to move on to
// the next message.
RefPtr<MboxMsgInputStream> mboxStream = new MboxMsgInputStream(raw, 0);
mMboxStream = mboxStream;
nsCOMPtr<nsIInputStreamPump> pump;
rv = NS_NewInputStreamPump(getter_AddRefs(pump), mboxStream.forget());

RefPtr<MboxMsgInputStream> rdr = new MboxMsgInputStream(raw, 0);

while (true) {
  nsAutoCString got;
  // Read a single message.
  rv = Slurp(rdr, readSize, got);
  if (NS_FAILED(rv)) {
    return rv;
  }

  // Add it to our collection
  msgs.AppendElement(got);

  // Try and reuse the MboxMsgInputStream for the next message.
  bool more;
  rv = rdr->Continue(more);
  if (NS_FAILED(rv)) {
    return rv;
  }
  if (!more) {
    break;
  }
